CREATE TABLE agents(id uuid PRIMARY KEY, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 60), avatar_url text, token_hash text UNIQUE NOT NULL, enabled boolean NOT NULL DEFAULT true, return_address text NOT NULL, per_bet_limit bigint CHECK(per_bet_limit>0), daily_limit bigint CHECK(daily_limit>0), metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rounds(id text PRIMARY KEY, start_at timestamptz NOT NULL UNIQUE, lock_at timestamptz NOT NULL, end_at timestamptz NOT NULL, phase text NOT NULL CHECK(phase IN ('UPCOMING','OPEN','LOCKED','RESOLVED','PAYING','PAID','VOIDED','REFUNDING','REFUNDED')), provider text NOT NULL, rules jsonb NOT NULL, opening numeric(24,8), closing numeric(24,8), outcome text CHECK(outcome IN ('UP','DOWN')), reason text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(start_at<lock_at AND lock_at<end_at));
CREATE TABLE price_observations(id bigserial PRIMARY KEY,provider text NOT NULL,pair text NOT NULL,provider_at timestamptz NOT NULL,received_at timestamptz NOT NULL,price numeric(24,8) NOT NULL CHECK(price>0),sequence text NOT NULL,payload jsonb NOT NULL,UNIQUE(provider,pair,sequence));
CREATE INDEX price_window ON price_observations(provider,provider_at);
CREATE TABLE bets(id uuid PRIMARY KEY,agent_id uuid NOT NULL REFERENCES agents,round_id text NOT NULL REFERENCES rounds,direction text NOT NULL CHECK(direction IN ('UP','DOWN')),amount bigint NOT NULL CHECK(amount>0 AND amount<=100000000),return_address text NOT NULL,idempotency_key text NOT NULL,request_hash text NOT NULL,status text NOT NULL CHECK(status IN ('CREATED','AWAITING_PAYMENT','PAID','ACCEPTED','LATE_PAYMENT','LOST','WON','PAYOUT_PENDING','PAID_OUT','REFUND_PENDING','REFUNDED','EXPIRED','FAILED')),accepted_at timestamptz,receive_reference text UNIQUE NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(agent_id,idempotency_key));
CREATE UNIQUE INDEX one_accepted_bet ON bets(agent_id,round_id) WHERE accepted_at IS NOT NULL;
CREATE INDEX bets_round ON bets(round_id);
CREATE TABLE incoming_payments(id text PRIMARY KEY,bet_id uuid NOT NULL REFERENCES bets,amount bigint NOT NULL CHECK(amount>0),received_at timestamptz NOT NULL,disposition text NOT NULL CHECK(disposition IN ('ACCEPTED','LATE_PAYMENT','AMOUNT_MISMATCH','DUPLICATE_BET','CLOSED_ROUND')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settlement_obligations(id text PRIMARY KEY,bet_id uuid NOT NULL REFERENCES bets,incoming_id text UNIQUE REFERENCES incoming_payments,kind text NOT NULL CHECK(kind IN ('PAYOUT','REFUND')),amount bigint NOT NULL CHECK(amount>0),destination text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_settlement_per_bet ON settlement_obligations(bet_id) WHERE incoming_id IS NULL;
CREATE TABLE outgoing_payments(id text PRIMARY KEY REFERENCES settlement_obligations,idempotency_reference text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SENDING','CONFIRMED','FAILED','UNKNOWN')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),provider_id text UNIQUE,last_error text,confirmed_at timestamptz);
CREATE TABLE market_events(id bigserial PRIMARY KEY,type text NOT NULL,round_id text REFERENCES rounds,data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX events_round ON market_events(round_id,id);
CREATE FUNCTION protect_events() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'market_events is append-only'; END; $$;
CREATE TRIGGER events_immutable BEFORE UPDATE OR DELETE ON market_events FOR EACH ROW EXECUTE FUNCTION protect_events();
CREATE TABLE system_settings(key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO system_settings(key,value) VALUES('paused','false');
CREATE TABLE mock_receipts(id text PRIMARY KEY,reference text NOT NULL,amount bigint NOT NULL CHECK(amount>0),received_at timestamptz NOT NULL);
CREATE TABLE mock_sends(reference text PRIMARY KEY,provider_id text UNIQUE NOT NULL,amount bigint NOT NULL,destination text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE write_limits(agent_id uuid PRIMARY KEY REFERENCES agents,window_at timestamptz NOT NULL,count integer NOT NULL);
